export interface TravelDistrict {
  /** 행정안전부 시군구 코드 다섯 자리. travel_visits.region_code에 그대로 저장된다. */
  code: string
  /** 이 시군구가 속한 시도 코드. */
  sido: string
  /** 정식 명칭 ("수원시 장안구"). */
  name: string
  /** 상위 시도 안에서만 보여줄 때 쓰는 짧은 이름 ("장안구"). */
  shortName: string
  /** 라벨과 탭 목표의 기준점 (뷰박스 좌표). regions.ts와 같은 좌표계다. */
  center: [number, number]
  /** 뷰박스 좌표에서의 최대 변 길이. */
  size: number
  /** SVG path의 d 속성. */
  path: string
}

